import { Group, Mesh, PlaneGeometry } from 'three/webgpu';
import { MeshStandardNodeMaterial, texture as texNode } from 'three/webgpu';
import { texture as texNodeFunc, uv, mix, smoothstep, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';
import * as primitives from '@/primitives';
import * as text from '@/text';

export default function createNode(config, ctx) {
  const group = new Group();

  // Geometry
  const geometry = new PlaneGeometry(1, 0.5, 64, 64);

  // Placeholder material (will be updated when textures load)
  const material = new MeshStandardNodeMaterial({
    color: config?.intent?.visualSpec?.colors?.paper ?? '#e8ecf2',
    metalness: 0.3,
    roughness: 0.6,
    clearcoat: 0.1,
  });

  const mesh = new Mesh(geometry, material);
  group.add(mesh);

  // Load textures asynchronously
  let imageTex, depthTex;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imageTex = tex;
      material.mapNode = texNodeFunc(imageTex);
      material.needsUpdate = true;
    });
  }
  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((tex) => {
      depthTex = tex;
      const depthMapNode = texNodeFunc(depthTex);
      material.displacementMapNode = depthMapNode;
      material.displacementScale = uniform(0.1);
      material.needsUpdate = true;
    });
  }

  // Apply parallax-scroll primitive for subtle cursor/camera parallax
  const parallax = ctx.primitives['parallax-scroll'](group, {
    intensity: 0.05,
    speed: 0.2,
  });

  // GSAP timeline for hover rise‑in effect
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(mesh.position, {
    y: mesh.position.y + 0.15,
    duration: 0.7,
    ease: 'power3.out',
  });

  // Event handlers
  group.userData.handlers = {
    hover: (enter) => {
      if (enter) hoverTl.play();
      else hoverTl.reverse();
    },
    click: () => {
      ctx.emit('hub-features.select');
    },
  };

  // Cleanup routine
  group.userData.cleanup = () => {
    hoverTl.kill();
    if (imageTex && imageTex.dispose) imageTex.dispose();
    if (depthTex && depthTex.dispose) depthTex.dispose();
    material.dispose();
    geometry.dispose();
    if (parallax && parallax.cleanup) parallax.cleanup();
  };

  return group;
}
